import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { adminService } from '../../services/adminService';
import LoadingSpinner from '../common/LoadingSpinner';
import { getErrorMessage, getStatusText, getStatusColor, formatDateTime } from '../../utils/helpers';

const ApplicationDetails = () => {
  const [application, setApplication] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { id } = useParams();
  const navigate = useNavigate();

  useEffect(() => {
    loadApplicationDetails();
  }, [id]);

  const loadApplicationDetails = async () => {
    try {
      setLoading(true);
      setError('');
      
      // Since we don't have a specific endpoint for application details,
      // we'll get all applications and find the one we need
      const response = await adminService.getAllApplications();
      const applicationData = response.data.find(app => app.id.toString() === id);
      
      if (applicationData) {
        setApplication(applicationData);
      } else {
        setError('Application not found');
      }
    } catch (error) {
      setError(getErrorMessage(error));
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <LoadingSpinner message="Loading application details..." />;
  }

  if (error) {
    return (
      <div className="application-details-page">
        <div className="container">
          <div className="error-container">
            <div className="error-message">
              <h2>Error Loading Application</h2>
              <p>{error}</p>
              <div className="error-actions">
                <button onClick={loadApplicationDetails} className="btn btn-primary">
                  Try Again
                </button>
                <button onClick={() => navigate('/admin/applications')} className="btn btn-outline">
                  Back to Applications
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!application) {
    return (
      <div className="application-details-page">
        <div className="container">
          <div className="not-found">
            <h2>Application Not Found</h2>
            <p>The application you're looking for doesn't exist or has been removed.</p>
            <button onClick={() => navigate('/admin/applications')} className="btn btn-primary">
              Back to All Applications
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="application-details-page">
      <div className="container">
        <div className="page-header">
          <div className="header-content">
            <button onClick={() => navigate('/admin/applications')} className="back-btn">
              ← Back to Applications
            </button>
            <h1>Application #{application.id}</h1>
            <div className={`status-badge large ${getStatusColor(application.status)}`}>
              {getStatusText(application.status)}
            </div>
          </div>
        </div>

        <div className="application-details-container">
          {/* Application Status Timeline */}
          <div className="details-section">
            <h3>Status Timeline</h3>
            <div className="timeline">
              <div className="timeline-item completed">
                <div className="timeline-marker"></div>
                <div className="timeline-content">
                  <h4>Created</h4>
                  <p>{formatDateTime(application.createdAt)}</p>
                </div>
              </div>

              {application.submittedAt && (
                <div className="timeline-item completed">
                  <div className="timeline-marker"></div>
                  <div className="timeline-content">
                    <h4>Submitted</h4>
                    <p>{formatDateTime(application.submittedAt)}</p>
                  </div>
                </div>
              )}

              {application.reviewedAt && (
                <div className="timeline-item completed">
                  <div className="timeline-marker"></div>
                  <div className="timeline-content">
                    <h4>Reviewed</h4>
                    <p>{formatDateTime(application.reviewedAt)}</p>
                  </div>
                </div>
              )}

              {application.inspectedAt && (
                <div className="timeline-item completed">
                  <div className="timeline-marker"></div>
                  <div className="timeline-content">
                    <h4>Inspected</h4>
                    <p>{formatDateTime(application.inspectedAt)}</p>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Vendor Information */}
          <div className="details-section">
            <h3>Vendor Information</h3>
            <div className="vendor-details">
              <div className="detail-grid">
                <div className="detail-item">
                  <label>Business Name:</label>
                  <span>{application.vendor?.name || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Owner Username:</label>
                  <span>{application.vendor?.user?.username || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Email:</label>
                  <span>{application.vendor?.user?.email || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Phone:</label>
                  <span>{application.vendor?.phoneNumber || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Operating Region:</label>
                  <span>{application.vendor?.operatingRegion || 'N/A'}</span>
                </div>
                <div className="detail-item">
                  <label>Cuisine Specialties:</label>
                  <span>{application.vendor?.cuisineSpecialties || 'N/A'}</span>
                </div>
              </div>

              {application.vendor?.businessAddress && (
                <div className="detail-item full-width">
                  <label>Business Address:</label>
                  <span>{application.vendor.businessAddress}</span>
                </div>
              )}

              {application.vendor?.menuHighlights && (
                <div className="detail-item full-width">
                  <label>Menu Highlights:</label>
                  <span>{application.vendor.menuHighlights}</span>
                </div>
              )}
            </div>
          </div>

          {/* Assignment Information */}
          <div className="details-section">
            <h3>Assignment Information</h3>
            <div className="assignment-details">
              <div className="detail-item">
                <label>Assigned Reviewer:</label>
                <span>{application.assignedReviewer?.username || 'Not assigned'}</span>
              </div>
              <div className="detail-item">
                <label>Assigned Inspector:</label>
                <span>{application.assignedInspector?.username || 'Not assigned'}</span>
              </div>
            </div>
          </div>

          {/* Comments */}
          {application.comments && (
            <div className="details-section">
              <h3>Comments</h3>
              <div className="comments-section">
                <p>{application.comments}</p>
              </div>
            </div>
          )}

          {/* License Information */}
          {application.vendor?.licenseNumber && (
            <div className="details-section">
              <h3>License Information</h3>
              <div className="license-details">
                <div className="detail-item">
                  <label>License Number:</label>
                  <span>{application.vendor.licenseNumber}</span>
                </div>
                {application.vendor.licenseExpiry && (
                  <div className="detail-item">
                    <label>License Expiry:</label>
                    <span>{formatDateTime(application.vendor.licenseExpiry)}</span>
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="details-actions">
            <button 
              onClick={() => navigate('/admin/applications')}
              className="btn btn-outline"
            >
              Back to Applications
            </button>
            
            {/* Future: Add status update buttons */}
            <div className="status-actions">
              <p className="note">Status update functionality will be available in future updates</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ApplicationDetails;
